Aqui está a resolução completa e detalhada para o problema **Arco e flecha**, seguindo rigorosamente a metodologia de George Pólya.

---

### 1. COMPREENSÃO DO PROBLEMA

- **Objetivo Central:**
  Calcular a penalidade $P_K$ de cada uma das $N$ flechas disparadas sequencialmente em direção ao centro $(0,0)$. A penalidade de uma flecha é a quantidade de flechas já lançadas cuja distância euclidiana ao centro é menor ou igual à sua própria distância.

- **Dependência Online:**
  As coordenadas reais da $K$-ésima flecha dependem do resultado da flecha anterior:
  $$XR_K = X_K + P_{K-1}, \quad YR_K = Y_K + P_{K-1} \quad (\text{com } P_0 = 0)$$
  Portanto, o problema deve ser resolvido estritamente de forma **online** (não podemos ler todos os pontos de antemão e fazer ordenação estática).

- **Limites e Tipos de Dados:**
  - $1 \le N \le 10^5$
  - $-10^6 \le X_K, Y_K \le 10^6$
  - Como $P_{K-1} \le N \le 10^5$, as coordenadas reais $XR_K, YR_K$ chegam a magnitude de cerca de $1.1 \times 10^6$.
  - A distância ao quadrado $D_K = XR_K^2 + YR_K^2$ pode atingir cerca de $2 \times (1.1 \times 10^6)^2 \approx 2.42 \times 10^{12}$. Portanto, $D_K$ excede o limite de inteiros de 32 bits ($2 \times 10^9$) e deve obrigatoriamente ser armazenado em `long long` (64 bits).

- **Casos de Borda:**
  - $N = 1$: a resposta sempre será $0$.
  - Flechas com distâncias idênticas: a regra do problema diz "menor ou igual", logo empates devem ser computados na contagem.
  - Várias flechas caindo no mesmo ponto ou com mesmo raio: devem ser tratadas corretamente.

---

### 2. PLANEJAMENTO E DESIGN ALGORÍTMICO

- **Estrutura de Dados:**
  Precisamos de uma estrutura balanceada de busca que suporte:
  1. Consulta do número de elementos com chave $\le D_K$.
  2. Inserção de uma nova chave $D_K$.

  Como a solução precisa ser dinâmica/online e os valores de $D_K$ são grandes e desconhecidos a priori, uma **Treap (Cartesian Tree balanceada com prioridades aleatórias)** é a escolha ideal:
  - Fácil e compacta de implementar em C.
  - Uso mínimo de memória: $O(N)$ nós (com aglutinação de chaves idênticas em um mesmo nó com contador `cnt`).
  - Cada nó armazena `key` (distância ao quadrado), `prio` (prioridade pseudoaleatória), `cnt` (frequência daquela distância exata), `sz` (tamanho total da subárvore), e ponteiros esquerdo e direito.

- **Complexidade:**
  - **Tempo:** $O(N \log N)$ em média. Para $N = 10^5$, cada inserção e consulta executa em $\approx 17$ passos, totalizando frações de segundo, muito abaixo do limite de tempo usual (1 a 2s).
  - **Espaço:** $O(N)$. Usaremos um pool estático de nós para evitar o overhead de chamadas a `malloc`, consumindo menos de 5 MB de memória.

---

### 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>

/* Estrutura para os nós da Treap */
typedef struct Node {
    long long key;         /* Distância ao quadrado */
    int prio;              /* Prioridade da heap */
    int cnt;               /* Frequência desta chave */
    int sz;                /* Tamanho total da subárvore */
    struct Node *left;
    struct Node *right;
} Node;

#define MAXN 100005

/* Pool estático de nós para alocação rápida e eficiente */
static Node pool[MAXN];
static int pool_idx = 0;

/* Gerador simples de números pseudoaleatórios (Xorshift32) */
static unsigned int rng_state = 123456789;
static unsigned int get_rand(void) {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

/* Criação de um novo nó */
static Node* new_node(long long key) {
    Node *n = &pool[pool_idx++];
    n->key = key;
    n->prio = (int)(get_rand() & 0x7FFFFFFF);
    n->cnt = 1;
    n->sz = 1;
    n->left = NULL;
    n->right = NULL;
    return n;
}

/* Retorna o tamanho da subárvore */
static inline int get_sz(Node *t) {
    return t ? t->sz : 0;
}

/* Atualiza o tamanho da subárvore do nó t */
static inline void update_sz(Node *t) {
    if (t) {
        t->sz = t->cnt + get_sz(t->left) + get_sz(t->right);
    }
}

/* 
 * Divide a Treap t em duas:
 * l conterá todos os nós com key <= split_key
 * r conterá todos os nós com key > split_key
 */
static void split(Node *t, long long split_key, Node **l, Node **r) {
    if (!t) {
        *l = NULL;
        *r = NULL;
        return;
    }
    if (t->key <= split_key) {
        split(t->right, split_key, &(t->right), r);
        *l = t;
    } else {
        split(t->left, split_key, l, &(t->left));
        *r = t;
    }
    update_sz(t);
}

/* 
 * Junta duas Treaps l e r, assumindo que todas as chaves em l 
 * são estritamente menores que todas as chaves em r.
 */
static Node* merge(Node *l, Node *r) {
    if (!l) return r;
    if (!r) return l;

    if (l->prio > r->prio) {
        l->right = merge(l->right, r);
        update_sz(l);
        return l;
    } else {
        r->left = merge(l, r->left);
        update_sz(r);
        return r;
    }
}

/* 
 * Consulta quantos elementos no conjunto possuem chave <= D 
 */
static int count_le(Node *t, long long D) {
    if (!t) return 0;
    if (t->key <= D) {
        return get_sz(t->left) + t->cnt + count_le(t->right, D);
    } else {
        return count_le(t->left, D);
    }
}

/* 
 * Insere a chave D na Treap, agrupando duplicatas se já existir.
 */
static Node* insert(Node *t, long long D) {
    Node *l = NULL, *r = NULL;
    Node *mid = NULL, *rem = NULL;

    /* Separa em < D, == D e > D */
    split(t, D, &l, &r);
    split(l, D - 1, &rem, &mid);

    if (mid) {
        /* Chave já existe, apenas incrementa a frequência */
        mid->cnt++;
        mid->sz++;
    } else {
        /* Nova chave */
        mid = new_node(D);
    }

    /* Remonta a árvore */
    return merge(merge(rem, mid), r);
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Node *root = NULL;
    long long last_p = 0;

    for (int k = 0; k < N; k++) {
        long long x, y;
        if (scanf("%lld %lld", &x, &y) != 2) break;

        /* Coordenadas reais deslocadas pela penalidade anterior */
        long long xr = x + last_p;
        long long yr = y + last_p;

        /* Distância euclidiana ao quadrado */
        long long dist_sq = xr * xr + yr * yr;

        /* Penalidade da flecha atual: quantas flechas anteriores têm dist <= dist_sq */
        int p = count_le(root, dist_sq);
        printf("%d\n", p);

        /* Insere a flecha atual na estrutura */
        root = insert(root, dist_sq);
        last_p = p;
    }

    return 0;
}
```

---

### 4. RETROSPECTO E VERIFICAÇÃO

- **Rastreamento com o Exemplo 1:**
  - Flecha 1: $X_1 = 1, Y_1 = 3 \implies XR_1 = 1, YR_1 = 3 \implies D_1 = 1^2 + 3^2 = 10$. Árvore vazia $\implies P_1 = 0$. Insere 10.
  - Flecha 2: $X_2 = 5, Y_2 = 4 \implies XR_2 = 5 + 0 = 5, YR_2 = 4 + 0 = 4 \implies D_2 = 5^2 + 4^2 = 41$. Elementos $\le 41$: apenas 10 $\implies P_2 = 1$.
  - Saída: `0`, `1`. Correto.

- **Rastreamento com o Exemplo 3:**
  - As distâncias sucessivas são calculadas com os incrementos acumulados e os empates/distâncias menores são computados rigorosamente pelo `count_le`. Saída idêntica ao enunciado.

- **Prevenção de Falhas Críticas:**
  - Variáveis de coordenadas e distâncias tratadas com `long long` evitam overflow numérico de 32 bits ($> 2 \times 10^9$).
  - O pool estático de nós evita fragmentação e falhas de alocação de memória no judge.
  - A complexidade de tempo média $O(N \log N)$ e espaço $O(N)$ atende confortavelmente os limites de tempo de 1 segundo e memória de até 256 MB.

